   244→    func provider(_ provider: CXProvider, perform action: CXAnswerCallAction) {
   245→        guard let incomingCallID else {
   246→            MXLog.error("Failed answering incoming call, missing incomingCallID")
   247→            return
   248→        }
   249→        
   250→        // Fixes broken videos on EC web when a CallKit session is established.
   251→        //
   252→        // Reporting an ongoing call through `reportNewIncomingCall` + `CXAnswerCallAction`
   253→        // or `reportOutgoingCall:connectedAt:` will give exclusive access for media to the
   254→        // ongoing process, which is different than the WKWebKit is running on, making EC
   255→        // unable to aquire media streams.
   256→        // Reporting the call as ended imediately after answering it works around that
   257→        // as EC gets access to media again and EX builds the right UI in `setupCallSession`
   258→        //
   259→        // https://developer.apple.com/forums//thread/767949?answerId=812951022#812951022
   260→        //
   261→        // https://github.com/element-hq/element-x-ios/issues/3041
   262→        // https://forums.developer.apple.com/forums/thread/685268
   263→        // https://stackoverflow.com/questions/71483732/webrtc-running-from-wkwebview-avaudiosession-development-roadblock
   264→        
   265→        // First fullfill the action
   266→        action.fulfill()
   267→        
   268→        // And delay ending the call so that the app has enough time
   269→        // to get deeplinked into
   270→        DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
   271→            // Then end the and call rely on `setupCallSession` to create a new one
   272→            provider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: .remoteEnded)
   273→            
   274→            self.actionsSubject.send(.startCall(roomID: incomingCallID.roomID))
   275→            self.endUnansweredCallTask?.cancel()
   276→        }
   277→    }
