   314→            let transaction = CXTransaction(action: CXEndCallAction(call: ongoingCallID.callKitID))
   315→            callController.request(transaction) { error in
   316→                if let error {
   317→                    MXLog.error("Failed transaction with error: \(error)")
   318→                }
   319→            }
   320→        }
