   325→    private func sendDeclineCallEvent(_ incomingCallID: CallID) async {
   326→        guard let rtcNotificationID = incomingCallID.rtcNotificationID else {
   327→            MXLog.info("No rtc notification event to decline.")
   328→            return
   329→        }
   330→        
   331→        guard let clientProxy else {
   332→            MXLog.warning("A ClientProxy is needed to fetch the room.")
   333→            return
   334→        }
   335→        
   336→        guard case let .joined(roomProxy) = await clientProxy.roomForIdentifier(incomingCallID.roomID) else {
   337→            MXLog.warning("Failed to fetch a joined room for the incoming call.")
   338→            return
   339→        }
   340→        
   341→        _ = await roomProxy.declineCall(notificationID: rtcNotificationID)
   342→    }
   343→    
   344→    private func observeIncomingCall() async {
   345→        incomingCallRoomInfoCancellable = nil
   346→        
   347→        guard let incomingCallID else {
   348→            MXLog.info("No incoming call to observe for.")
   349→            return
   350→        }
   351→        
   352→        guard let clientProxy else {
   353→            MXLog.warning("A ClientProxy is needed to fetch the room.")
   354→            return
   355→        }
   356→        
   357→        guard case let .joined(roomProxy) = await clientProxy.roomForIdentifier(incomingCallID.roomID) else {
   358→            MXLog.warning("Failed to fetch a joined room for the incoming call.")
   359→            return
   360→        }
   361→        
   362→        roomProxy.subscribeToRoomInfoUpdates()
   363→        
   364→        incomingCallRoomInfoCancellable = roomProxy
   365→            .infoPublisher
   366→            .compactMap { ($0.hasRoomCall, $0.activeRoomCallParticipants) }
   367→            .removeDuplicates { $0 == $1 }
   368→            .drop { hasRoomCall, _ in
   369→                // Filter all updates before hasRoomCall becomes `true`. Then we can correctly
   370→                // detect its change to `false` to stop ringing when the caller hangs up.
   371→                !hasRoomCall
   372→            }
   373→            .sink { [weak self] hasOngoingCall, activeRoomCallParticipants in
   374→                guard let self else { return }
   375→                
   376→                let participants: [String] = activeRoomCallParticipants
   377→                
   378→                if !hasOngoingCall {
   379→                    MXLog.info("Call cancelled by remote")
   380→                    reportEndedCall(incomingCallID: incomingCallID, reason: .remoteEnded)
   381→                } else if participants.contains(roomProxy.ownUserID) {
   382→                    MXLog.info("Call answered elsewhere")
   383→                    reportEndedCall(incomingCallID: incomingCallID, reason: .answeredElsewhere)
   384→                }
   385→            }
   386→        
   387→        guard let rtcNotificationID = incomingCallID.rtcNotificationID else {
   388→            MXLog.warning("Decline: No RTC notification ID found for the incoming call.")
   389→            return
   390→        }
   391→        
   392→        MXLog.info("Observe decline events for notification \(rtcNotificationID)")
   393→        
   394→        let listener: CallDeclineListener = SDKListener { [weak self] senderID in
   395→            guard let self else { return }
   396→            
   397→            MXLog.debug("Call declined event received from \(senderID)")
   398→            
   399→            if senderID == roomProxy.ownUserID {
   400→                // Stop ringing!
   401→                MXLog.debug("Call declined elsewhere")
   402→                reportEndedCall(incomingCallID: incomingCallID, reason: .declinedElsewhere)
   403→            }
   404→        }
   405→        
   406→        guard case let .success(handle) = roomProxy.subscribeToCallDeclineEvents(rtcNotificationEventID: rtcNotificationID, listener: listener) else {
   407→            MXLog.error("Unable to listen for decline events.")
   408→            return
   409→        }
   410→        
   411→        declineListenerHandle = handle
   412→    }
   413→    
   414→    private func reportEndedCall(incomingCallID: CallID, reason: CXCallEndedReason) {
   415→        declineListenerHandle?.cancel()
   416→        declineListenerHandle = nil
   417→        endUnansweredCallTask?.cancel()
   418→        callProvider.reportCall(with: incomingCallID.callKitID, endedAt: nil, reason: reason)
   419→    }
   420→}
