```

---

### 4. **PushKit (PKPushRegistry) Integration**

#### VoIP Push Registration
The `ElementCallService` manages PushKit:

```swift
private let pushRegistry: PKPushRegistry

init(...) {
    pushRegistry = PKPushRegistry(queue: nil)
    // ... initialization ...
    pushRegistry.delegate = self
    pushRegistry.desiredPushTypes = [.voIP]  // Request VoIP push tokens
}

// PKPushRegistryDelegate - called when push credentials change
func pushRegistry(_ registry: PKPushRegistry, didUpdate pushCredentials: PKPushCredentials, 
                  for type: PKPushType) { 
    // The main app doesn't handle push credentials here
    // The NSE decrypts and routes VoIP pushes via CXProvider.reportNewIncomingVoIPPushPayload
}
```

#### VoIP Push Payload Structure

From `ElementCallServiceConstants.swift`:
```swift
enum ElementCallServiceNotificationKey: String {
    case roomID                    // Matrix room ID
    case roomDisplayName           // Display name for CallKit UI
    case rtcNotifyEventID          // m.rtc.notification event ID for declining
    case expirationDate            // When the call ring should expire
}

let ElementCallServiceNotificationDiscardDelta = 15.0  // 15 second window to validate call is fresh
```

---

### 5. **NSE-to-CallKit Flow: CXProvider.reportNewIncomingVoIPPushPayload**

**`/Users/stjepandzojic/projects/element-x-ios/NSE/Sources/NotificationHandler.swift`**

The NSE intercepts call notifications and routes them through CallKit:

```swift
private func handleCallNotification(notificationType: RtcNotificationType,
                                    rtcNotifyEventID: String,
                                    timestamp: Timestamp,
                                    expirationTimestamp: Timestamp,
                                    roomID: String,
                                    roomDisplayName: String) async -> NotificationProcessingResult {

    // Only handle "ring" notification types as VoIP calls
    guard notificationType == .ring else {
        return .shouldDisplay  // Show as normal notification
    }

    // Check if call is still ongoing in the room
    if let room = userSession.roomForIdentifier(roomID) {
        if !room.hasActiveRoomCall() {
            // Wait up to 5 seconds for room info to update
            let expiringTask = ExpiringTaskRunner {
                await withCheckedContinuation { [weak self] continuation in
                    self?.roomInfoObservationToken = room.subscribeToRoomInfoUpdates(listener: SDKListener { info in
                        if info.hasRoomCall {
                            continuation.resume()
                        }
                    })
                }
            }

            try? await expiringTask.run(timeout: .seconds(5))

            guard room.hasActiveRoomCall() else {
                return .shouldDisplay  // No active call, show as regular notification
            }
        }
    } else {
        // Fallback: check if notification is recent (within 15 seconds)
        let timestamp = Date(timeIntervalSince1970: TimeInterval(timestamp / 1000))
        guard abs(timestamp.timeIntervalSinceNow) < ElementCallServiceNotificationDiscardDelta else {
            return .shouldDisplay  // Old notification, show as regular notification
        }
    }

    // Build the VoIP push payload for the main app
    let payload = [
        ElementCallServiceNotificationKey.roomID.rawValue: roomID,
        ElementCallServiceNotificationKey.roomDisplayName.rawValue: roomDisplayName,
        ElementCallServiceNotificationKey.expirationDate.rawValue: expirationDate,
        ElementCallServiceNotificationKey.rtcNotifyEventID.rawValue: rtcNotifyEventID
    ] as [String: Any]

    do {
        // KEY LINE: This tells the system to wake the main app and deliver 
        // the payload to PKPushRegistry.didReceiveIncomingPushWith
        try await CXProvider.reportNewIncomingVoIPPushPayload(payload)
        MXLog.info("Call notification delegated to CallKit")
    } catch {
        MXLog.error("Failed reporting voip call with error: \(error). Handling as push notification")
        return .shouldDisplay  // Fall back to regular notification
    }

    return .processedShouldDiscard  // Discard the regular notification
}
```

**How This Works:**
1. NSE receives encrypted push notification
2. NSE decrypts it and identifies it as a call notification
3. NSE calls `CXProvider.reportNewIncomingVoIPPushPayload(payload)`
4. This wakes the main app (even if terminated) and queues a VoIP push
5. Main app's `PKPushRegistry.didReceiveIncomingPushWith` is called
6. Main app calls `CXProvider.reportNewIncomingCall` to show CallKit UI

