### 7. **Background App Refresh and Sync Management**

When a VoIP push is received, the app must sync to get the latest room state:

```swift
private func startSync() {
    guard let userSession else { return }

    ServiceLocator.shared.analytics.signpost.startTransaction(.upToDateRoomList)
    userSession.clientProxy.startSync()  // Start sync

    // Observe sync responses
    clientProxyObserver = userSession.clientProxy
        .actionsPublisher
        .sink { [weak self] action in
            // Handle sync response
        }
}

private func scheduleDelayedSyncStop() {
    guard backgroundTask == nil else { return }

    // Request background time from the OS
    backgroundTask = appMediator.beginBackgroundTask { [weak self] in
        self?.stopSync()
    }

    // Stop sync after a delay (allows time for syncing)
    DispatchQueue.main.asyncAfter(deadline: .now() + 3.0) { [weak self] in
        self?.stopSync()
    }
}
```

